widget_def.init:
var root=container;
root.innerHTML='<div style="background:#0d0f14;font-family:system-ui,sans-serif;padding:12px;color:#e5e7eb;display:flex;flex-direction:column;gap:10px">'
+'<div style="font-weight:700;font-size:13px">⚠️ Nomogramme paracétamol (Rumack-Matthew)</div>'
+'<div style="background:#111827;border:1px solid rgba(58,176,158,.25);border-radius:8px;padding:10px">'
+'<canvas id="pa-cv" style="width:100%;border-radius:8px;display:block;background:#0a0e1a"></canvas>'
+'<div style="font-size:10px;color:#9ca3af;text-transform:uppercase;margin-top:8px">Délai post-ingestion <span id="pa-t-l" style="color:#3ab09e">4</span> h</div>'
+'<input type="range" id="pa-t" min="4" max="24" value="4" step="0.5" style="width:100%;accent-color:#3ab09e">'
+'<div style="font-size:10px;color:#9ca3af;text-transform:uppercase;margin-top:6px">Paracétamolémie <span id="pa-c-l" style="color:#3ab09e">150</span> mg/L</div>'
+'<input type="range" id="pa-c" min="5" max="500" value="150" step="5" style="width:100%;accent-color:#3ab09e">'
+'<div id="pa-verdict" style="text-align:center;font-size:13px;font-weight:700;padding:8px;border-radius:6px;margin-top:8px"></div>'
+'<div style="font-size:9px;color:#6b7280;margin-top:6px;line-height:1.5">Ligne de traitement (200 mg/L à 4h, demi-vie 4h). Au-dessus → N-acétylcystéine (NAC). Dosage fiable seulement ≥ 4h post-ingestion. Référence : ligne « 150 » (UK) plus prudente.</div>'
+'</div></div>';
var cv=root.querySelector('#pa-cv'),ctx=cv.getContext('2d');
// Treatment line: C(t)=200*2^(-(t-4)/4) [Rumack 200 line]; we also draw 150 line.
function line200(t){return 200*Math.pow(2,-(t-4)/4);}
function line150(t){return 150*Math.pow(2,-(t-4)/4);}
function draw(){
  var W=cv.offsetWidth||320;cv.width=W;cv.height=190;
  var t=+root.querySelector('#pa-t').value,c=+root.querySelector('#pa-c').value;
  root.querySelector('#pa-t-l').textContent=t;root.querySelector('#pa-c-l').textContent=c;
  ctx.clearRect(0,0,W,190);
  var padL=34,padB=22,padT=8,padR=8,w=W-padL-padR,h=190-padT-padB;
  var tmin=4,tmax=24,cmin=5,cmax=500;
  function px(x){return padL+w*(x-tmin)/(tmax-tmin);}
  function py(y){var lo=Math.log(cmin),hi=Math.log(cmax);return padT+h*(1-(Math.log(y)-lo)/(hi-lo));}
  // axes
  ctx.strokeStyle='rgba(255,255,255,.12)';ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(padL,padT);ctx.lineTo(padL,padT+h);ctx.lineTo(padL+w,padT+h);ctx.stroke();
  ctx.fillStyle='#6b7280';ctx.font='8px monospace';ctx.textAlign='right';
  [10,50,100,200,500].forEach(function(v){if(v>=cmin&&v<=cmax){ctx.fillText(v,padL-3,py(v)+3);ctx.strokeStyle='rgba(255,255,255,.05)';ctx.beginPath();ctx.moveTo(padL,py(v));ctx.lineTo(padL+w,py(v));ctx.stroke();}});
  ctx.textAlign='center';[4,8,12,16,20,24].forEach(function(v){ctx.fillText(v+'h',px(v),padT+h+12);});
  // treatment lines
  function plot(fn,col,dash){ctx.strokeStyle=col;ctx.lineWidth=2;ctx.setLineDash(dash||[]);ctx.beginPath();for(var x=tmin;x<=tmax;x+=0.5){var y=fn(x);if(y<cmin)y=cmin;var X=px(x),Y=py(y);x===tmin?ctx.moveTo(X,Y):ctx.lineTo(X,Y);}ctx.stroke();ctx.setLineDash([]);}
  plot(line200,'#fbbf24');plot(line150,'#60a5fa',[4,3]);
  // patient point
  var X=px(Math.max(tmin,Math.min(tmax,t))),Y=py(Math.max(cmin,Math.min(cmax,c)));
  var toxic=c>=line200(t);
  ctx.fillStyle=toxic?'#ef4444':'#3ab09e';ctx.beginPath();ctx.arc(X,Y,5,0,2*Math.PI);ctx.fill();
  ctx.strokeStyle='#fff';ctx.lineWidth=1.5;ctx.stroke();
  var v=root.querySelector('#pa-verdict');
  if(t<4){v.textContent='Dosage non interprétable (< 4h)';v.style.background='rgba(156,163,175,.15)';v.style.color='#9ca3af';}
  else if(toxic){v.textContent='🚨 Au-dessus du seuil → NAC indiquée';v.style.background='rgba(248,113,113,.15)';v.style.color='#f87171';}
  else if(c>=line150(t)){v.textContent='⚠️ Zone intermédiaire (ligne 150) — discuter NAC';v.style.background='rgba(251,191,36,.15)';v.style.color='#fbbf24';}
  else{v.textContent='✓ Sous le seuil de traitement';v.style.background='rgba(58,176,158,.15)';v.style.color='#3ab09e';}
}
root.querySelector('#pa-t').addEventListener('input',draw);
root.querySelector('#pa-c').addEventListener('input',draw);
setTimeout(draw,50);draw();

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var v=+q('mh-m').value,g6=q('mh-g6').checked,nn=q('mh-nn').checked;
q('mh-o2').textContent=(100-v).toFixed(0);
var m=q('mh-msg'),txt='';
if(v>=70){txt='🚨 <b>PRONOSTIC VITAL ENGAGÉ</b> — exsanguino-transfusion ou oxygénothérapie hyperbare';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(v>=50){txt='🚨 Troubles de conscience, arythmies — traitement en urgence';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(v>=30){txt='⚠️ Céphalées, dyspnée, tachycardie — <b>bleu de méthylène 1 à 2 mg/kg IV</b> indiqué';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else if(v>=15){txt='Cyanose GRISE ARDOISÉE ne répondant pas à l\'O₂, avec PaO₂ normale et SpO₂ faussement rassurante';m.style.background='rgba(59,130,246,.15)';m.style.color='#60a5fa';}
else{txt='Taux faible — surveillance, éviction de l\'agent oxydant';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}
if(g6&&v>=20){txt='⛔ <b>DÉFICIT EN G6PD : bleu de méthylène CONTRE-INDIQUÉ</b> (inefficace et hémolysant) → exsanguino-transfusion ou O₂ hyperbare';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(nn&&v>=10){txt+='<br>👶 Nourrisson : vulnérabilité majorée (HbF plus oxydable, immaturité de la cytochrome b5 réductase)';}
m.innerHTML=txt;}
bind(['mh-m','mh-g6','mh-nn'],u);

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var v=+q('et-v').value,p=+q('et-p').value,r=+q('et-s').value,t=+q('et-t').value;
var c0=v*10/(p*r);var c=Math.max(0,c0-0.15*t);
q('et-a').textContent=c.toFixed(2);q('et-z').textContent=(c/0.15).toFixed(1);
var m=q('et-msg');
if(c>=3){m.innerHTML='🚨 <b>COMA ÉTHYLIQUE</b> — hypotonie, aréflexie, hypothermie, dépression respiratoire. Rechercher hypoglycémie, inhalation, traumatisme crânien';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(c>=1.5){m.innerHTML='⚠️ Phase d\'incoordination — ataxie, dysarthrie, diplopie';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else if(c>=0.5){m.innerHTML='Phase d\'excitation et de désinhibition — conduite interdite (limite légale 0,5 g/L, 0,2 g/L jeune conducteur)';m.style.background='rgba(59,130,246,.15)';m.style.color='#60a5fa';}
else{m.innerHTML='Sous le seuil légal — l\'élimination suit une cinétique d\'<b>ORDRE 0</b> à environ 0,15 g/L/h, non accélérable';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}}
bind(['et-v','et-p','et-s','et-t'],u);

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var h0=+q('co-h').value,t=+q('co-t').value,th=+q('co-m').value/60;
var h=h0*Math.pow(0.5,t/th);q('co-r').textContent=h.toFixed(1);
q('co-n').textContent=(h0>5)?(th*Math.log(h0/5)/Math.log(2)).toFixed(1):'0';
var m=q('co-msg');
if(h0>=25){m.innerHTML='🚨 Intoxication SÉVÈRE — oxygénothérapie hyperbare à discuter (perte de connaissance, signes neurologiques, atteinte cardiaque, <b>grossesse quel que soit le taux</b>)';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(h0>=10){m.innerHTML='⚠️ Intoxication modérée — O₂ normobare 100 % au masque haute concentration, <b>au moins 6 à 12 h</b>';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else{m.innerHTML='Taux bas — mais un taux bas <b>n\'exclut pas</b> l\'intoxication : interpréter selon le délai et l\'O₂ déjà reçu';m.style.background='rgba(59,130,246,.15)';m.style.color='#60a5fa';}}
bind(['co-h','co-t','co-m'],u);

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var v=+q('pb-p').value,e=q('pb-e').checked;
q('pb-s').textContent=e?'50':'100';
var m=q('pb-msg');
if(v>=450){m.innerHTML='🚨 <b>CHÉLATION URGENTE</b> (EDTA calcicodisodique, DMSA ; BAL + EDTA si encéphalopathie) + éviction immédiate de la source';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(v>=250){m.innerHTML='⚠️ Chélation à discuter, enquête environnementale, supplémentation fer et calcium';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else if(v>=(e?50:100)){m.innerHTML='📋 Dépassement du seuil — <b>déclaration obligatoire chez l\'enfant</b>, enquête environnementale, dépistage de la fratrie, suivi rapproché';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else{m.innerHTML='Sous le seuil de vigilance — mais <b>aucun seuil sans effet</b> n\'est établi pour la neurotoxicité développementale : la prévention primaire reste la priorité';m.style.background='rgba(59,130,246,.15)';m.style.color='#60a5fa';}}
bind(['pb-p','pb-e'],u);

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var d=+q('sa-d').value,p=+q('sa-p').value;var mg=d/p;
q('sa-mg').textContent=mg.toFixed(0);q('sa-cp').textContent=(d/500).toFixed(1);
var m=q('sa-msg');
if(mg>=500){m.innerHTML='🚨 <b>POTENTIELLEMENT MORTELLE</b> — hémodialyse à discuter d\'emblée. Piège : ne pas intuber sans maintenir la ventilation minute compensatrice';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(mg>=300){m.innerHTML='⚠️ Intoxication SÉVÈRE — alcalinisation (pH urinaire > 7,5) après correction de l\'<b>hypokaliémie</b>, charbon activé répété';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(mg>=150){m.innerHTML='Intoxication symptomatique — acouphènes, hyperventilation. Surveiller le trouble ACIDO-BASIQUE MIXTE (alcalose respiratoire + acidose métabolique)';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else{m.innerHTML='Dose infratoxique — surveillance simple ; attention à l\'absorption PROLONGÉE des formes gastro-résistantes (jusqu\'à 12 h)';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}}
bind(['sa-d','sa-p'],u);
